[tool_call Write] {"file_path":"ghql/client.ts","content":"// Minimal GitHub GraphQL client speaking the wire contract pinned in
// docs/contract.json: POST {base}/graphql, lowercase 'bearer' auth scheme,
// JSON body with a query string and a separate variables object.
// Zero dependencies — node built-ins (global fetch) only.

export interface GraphQLClientOptions {
  baseUrl: string;
  token: string;
  userAgent?: string;
}

export interface GraphQLErrorEntry {
  message?: string;
  type?: string;
  path?: Array<string | number>;
  [key: string]: unknown;
}

export interface RateHeaders {
  limit: number | null;
  remaining: number | null;
  used: number | null;
  reset: number | null;
  resource: string | null;
}

export interface ExecuteResult {
  data: any;
  errors: GraphQLErrorEntry[] | null;
  rateHeaders: RateHeaders;
}

// Credentials must never surface through error text or preserved error
// payloads. Scrubs the exact token when known, plus token-shaped strings and
// any 'bearer' auth material as a backstop for secrets we were not told about.
const TOKEN_PATTERNS = [/\bgh[pousr]_[A-Za-z0-9_]+/g, /\bgithub_pat_[A-Za-z0-9_]+/g];

function scrubString(text: string, secrets: readonly string[]): string {
  let out = text;
  for (const secret of secrets) {
    if (secret) out = out.split(secret).join("[redacted]");
  }
  for (const pattern of TOKEN_PATTERNS) out = out.replace(pattern, "[redacted]");
  out = out.replace(/bearer(\s+\S+)?/gi, "[redacted]");
  return out;
}

function scrubDeep(value: unknown, secrets: readonly string[]): unknown {
  if (typeof value === "string") return scrubString(value, secrets);
  if (Array.isArray(value)) return value.map((v) => scrubDeep(v, secrets));
  if (value !== null && typeof value === "object") {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value)) {
      out[scrubString(k, secrets)] = scrubDeep(v, secrets);
    }
    return out;
  }
  return value;
}

export class GraphQLHttpError extends Error {
  readonly status: number;

  constructor(status: number, serverMessage: string, secrets: readonly string[] = []) {
    super(scrubString(`GraphQL request failed with HTTP ${status}: ${serverMessage}`, secrets));
    this.name = "GraphQLHttpError";
    this.status = status;
  }
}

export class GraphQLQueryError extends Error {
  readonly errors: GraphQLErrorEntry[];

  constructor(message: string, errors: unknown[], secrets: readonly string[] = []) {
    super(scrubString(message, secrets));
    this.name = "GraphQLQueryError";
    // The preserved errors array is scrubbed too — it is just as reachable
    // as the message and must never carry credentials.
    this.errors = (Array.isArray(errors) ? errors : []).map(
      (e) => scrubDeep(e, secrets) as GraphQLErrorEntry,
    );
  }
}

function headerNumber(value: string | null): number | null {
  if (value === null || value.trim() === "") return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function parseRateHeaders(headers: Headers): RateHeaders {
  return {
    limit: headerNumber(headers.get("x-ratelimit-limit")),
    remaining: headerNumber(headers.get("x-ratelimit-remaining")),
    used: headerNumber(headers.get("x-ratelimit-used")),
    reset: headerNumber(headers.get("x-ratelimit-reset")),
    resource: headers.get("x-ratelimit-resource"),
  };
}

export class GraphQLClient {
  readonly #endpoint: string;
  readonly #token: string;
  readonly #userAgent: string;

  constructor(options: GraphQLClientOptions) {
    this.#endpoint = options.baseUrl.replace(/\/+$/, "") + "/graphql";
    this.#token = options.token;
    this.#userAgent = options.userAgent ?? "ghe-asset-inventory/1.0";
  }

  get #secrets(): string[] {
    return [`bearer ${this.#token}`, this.#token];
  }

  async execute(query: string, variables: Record<string, unknown> = {}): Promise<ExecuteResult> {
    const response = await fetch(this.#endpoint, {
      method: "POST",
      headers: {
        authorization: `bearer ${this.#token}`,
        "content-type": "application/json",
        accept: "application/json",
        "user-agent": this.#userAgent,
      },
      body: JSON.stringify({ query, variables }),
    });

    const raw = await response.text();

    if (response.status < 200 || response.status >= 300) {
      let serverMessage = raw;
      try {
        const parsed = JSON.parse(raw);
        if (parsed && typeof parsed.message === "string") serverMessage = parsed.message;
      } catch {
        // non-JSON error body (e.g. plain-text 502): use it as-is
      }
      throw new GraphQLHttpError(response.status, serverMessage, this.#secrets);
    }

    let envelope: any;
    try {
      envelope = raw === "" ? {} : JSON.parse(raw);
    } catch {
      throw new GraphQLQueryError(
        "GraphQL response was not valid JSON",
        [{ message: scrubString(raw.slice(0, 200), this.#secrets) }],
        this.#secrets,
      );
    }

    const errors = Array.isArray(envelope?.errors)
      ? envelope.errors.map((e: unknown) => scrubDeep(e, this.#secrets) as GraphQLErrorEntry)
      : null;

    return {
      data: envelope?.data ?? null,
      errors,
      rateHeaders: parseRateHeaders(response.headers),
    };
  }
