// Walks the repositories connection with cursor pagination exactly as the
// official pagination guide describes: pass each response's pageInfo.endCursor
// verbatim as the next request's $after, stop when hasNextPage is false.

import {
  GraphQLClient,
  GraphQLHttpError,
  GraphQLQueryError,
  type GraphQLErrorEntry,
  type RateHeaders,
} from "./client.ts";

export interface RepositoryNode {
  id: string;
  name: string;
  nameWithOwner: string;
  isArchived: boolean;
  visibility: string;
  pushedAt: string | null;
}

export interface RateLimitInfo {
  limit: number;
  cost: number;
  remaining: number;
  used: number;
  resetAt: string;
}

export interface InventoryWarning {
  message: string;
  type?: string;
  path?: Array<string | number>;
}

export interface InventoryReport {
  repositories: RepositoryNode[];
  totalCount: number;
  pagesFetched: number;
  duplicatesDropped: number;
  warnings: InventoryWarning[];
  rateLimit: RateLimitInfo | null;
  rateHeaders: RateHeaders;
}

export interface CollectOptions {
  pageSize?: number;
}

// The documented cap on the first/last connection arguments.
const MAX_PAGE_SIZE = 100;

// One parameterized operation: login, page size, and cursor all travel as
// GraphQL variables, never interpolated into the query text.
const INVENTORY_QUERY = `query OrgRepositoryInventory($login: String!, $first: Int!, $after: String) {
  organization(login: $login) {
    repositories(first: $first, after: $after) {
      totalCount
      pageInfo {
        hasNextPage
        endCursor
      }
      nodes {
        id
        name
        nameWithOwner
        isArchived
        visibility
        pushedAt
      }
    }
  }
  rateLimit {
    limit
    cost
    remaining
    used
    resetAt
  }
}`;

function clampPageSize(requested: number | undefined): number {
  if (requested === undefined || !Number.isFinite(requested)) return MAX_PAGE_SIZE;
  return Math.min(MAX_PAGE_SIZE, Math.max(1, Math.floor(requested)));
}

function isTransient(err: unknown): boolean {
  return err instanceof GraphQLHttpError && (err.status === 502 || err.status === 503);
}

function toWarning(error: GraphQLErrorEntry): InventoryWarning {
  const warning: InventoryWarning = {
    message: typeof error.message === "string" ? error.message : "GraphQL error",
  };
  if (typeof error.type === "string") warning.type = error.type;
  if (Array.isArray(error.path)) warning.path = error.path;
  return warning;
}

export async function collectRepositories(
  client: GraphQLClient,
  login: string,
  opts: CollectOptions = {},
): Promise<InventoryReport> {
  const first = clampPageSize(opts.pageSize);

  const repositories: RepositoryNode[] = [];
  const seenIds = new Set<string>();
  const warnings: InventoryWarning[] = [];
  let duplicatesDropped = 0;
  let totalCount = 0;
  let pagesFetched = 0;
  let rateLimit: RateLimitInfo | null = null;
  let rateHeaders: RateHeaders = {
    limit: null,
    remaining: null,
    used: null,
    reset: null,
    resource: null,
  };

  let after: string | null = null;
  let hasNextPage = true;

  while (hasNextPage) {
    const variables = { login, first, after };
    let result;
    try {
      result = await client.execute(INVENTORY_QUERY, variables);
    } catch (err) {
      if (!isTransient(err)) throw err;
      // Transient 502/503: retry exactly once with the identical cursor.
      // A second consecutive failure propagates to the caller.
      result = await client.execute(INVENTORY_QUERY, variables);
    }
    pagesFetched += 1;

    const connection = result.data?.organization?.repositories;
    if (!connection) {
      throw new GraphQLQueryError(
        result.errors?.[0]?.message ??
          `GraphQL response carried no repository data for the requested organization`,
        result.errors ?? [],
      );
    }

    if (result.errors) {
      // 200 with both data and errors is partial success: keep the good
      // nodes, surface every error as a warning on the report.
      warnings.push(...result.errors.map(toWarning));
    }

    totalCount = connection.totalCount ?? totalCount;

    const nodes: Array<RepositoryNode | null> = Array.isArray(connection.nodes)
      ? connection.nodes
      : [];
    for (const node of nodes) {
      if (node === null || node === undefined) continue;
      if (seenIds.has(node.id)) {
        // A retried page can overlap the previous one; dedupe by node id,
        // first-seen order wins.
        duplicatesDropped += 1;
        continue;
      }
      seenIds.add(node.id);
      repositories.push(node);
    }

    // The report reflects the LAST page's rate-limit state exactly — no
    // falling back to an earlier page when the final response omits it.
    rateLimit = result.data.rateLimit ?? null;
    rateHeaders = result.rateHeaders;

    const pageInfo = connection.pageInfo ?? { hasNextPage: false, endCursor: null };
    hasNextPage = pageInfo.hasNextPage === true;
    after = pageInfo.endCursor ?? null;
  }

  return {
    repositories,
    totalCount,
    pagesFetched,
    duplicatesDropped,
    warnings,
    rateLimit,
    rateHeaders,
  };
}
